#!/bin/zsh
# prof.sh <bin> <name> <src> [extra args]
# -> runs/<name>.rss (t_ms rss_mib every 50 ms), runs/<name>.log (t_ms stderr line), runs/<name>.time, runs/<name>.json
bin=$1; name=$2; src=$3; shift 3
d=/Users/gabe/Projects/caliper-fixtures/oracle-run/mem/runs
mkdir -p $d
cache=$d/cache-$name
rm -rf $cache; mkdir -p $cache
t0=$(perl -MTime::HiRes=time -e 'printf "%.3f", time')
/usr/bin/time -l -o $d/$name.time $bin extract --src $src --json --load-dependencies --collapse-inherited-props dependencies --cache-dir $cache "$@" > $d/$name.json 2> >(perl -MTime::HiRes=time -ne "printf '%d %s', (time-$t0)*1000, \$_" > $d/$name.log) &
tpid=$!
pid=""; for i in {1..200}; do pid=$(pgrep -n -f "release/caliper-docgen extract --src $src"); [[ -n $pid ]] && break; sleep 0.005; done
perl -MTime::HiRes=time,sleep -e "while(1){my \$r=\`ps -o rss= -p $pid\`; last unless \$r=~/\\d/; printf qq{%d %d\\n}, (time-$t0)*1000, \$r/1024; sleep 0.05}" > $d/$name.rss
wait $tpid
sleep 0.3
echo "$name peak_mib=$(awk '/maximum resident/{printf "%d",$1/1048576}' $d/$name.time) footprint_mib=$(awk '/peak memory footprint/{printf "%d",$1/1048576}' $d/$name.time) real=$(awk '/ real /{print $1}' $d/$name.time) json=$(stat -f %z $d/$name.json) sampled_max=$(sort -k2 -n $d/$name.rss | tail -1 | awk '{print $2"@"$1"ms"}') load=$(sysctl -n vm.loadavg)"

