uptime
for c in chakra shadcn mantine sbdemo; do CAL_READS_OUT=$M/runs/$c.reads MIMALLOC_SHOW_STATS=1 zsh $M/prof.sh $BM $c-im $S[$c]; done
for c in chakra shadcn mantine; do MIMALLOC_SHOW_STATS=1 zsh $M/prof.sh $BP $c-ip $S[$c]; done
