import json, sys, collections
for p in sys.argv[1:]:
    d = json.load(open(p)); comps = d.get('components')
    comps = list(comps.values()) if isinstance(comps, dict) else comps
    layers = [l for c in comps if isinstance(c, dict) for l in (c.get('inheritedLayers') or c.get('inherited_layers') or c.get('layers') or [])]
    names = [m for l in layers for m in (l.get('members') or [])]
    diags = collections.Counter(x.get('code') for x in d.get('diagnostics', []))
    print(p.split('/')[-1], 'components', len(comps), 'layers', len(layers), 'layer names', len(names), 'distinct', len(set(names)), 'name bytes', sum(map(len, names)), 'diags', diags.most_common(3), 'keys', list(d)[:8])
EOF

