1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] gathered for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row, a name in its collapsed
5	//! layer's `used` list, left in that layer, or unknown because the body says nothing. It is pure and total: no I/O, no
6	//! name lists, and its output follows the order of the members it is given.
7	//!
8	//! [`apply`] is its one caller, where a structural answer becomes output (`pipeline::revision`): the [`Inputs`]
9	//! gathered with the answer's resolution (so their reads are its dependencies) and the revision's call-site counts
10	//! (counted again each revision, so an edit to a consumer reaches every component it renders). The checker's merges
11	//! keep the inheritance layers, and so the `used` lists, of the structural answer.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::BTreeSet;
18	
19	use crate::types::output::{ComponentEntry, InheritedLayer, PropParent};
20	
21	/// The evidence about one component gathered with its resolution: what its props type writes and what its body does.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// The component's place in the project, which its call-site count is looked up by.
25	    pub(crate) site: call_sites::SiteKey,
26	    /// What the props type writes itself.
27	    pub(crate) props_type: props_type::PropsType,
28	    /// What the component's body does with its props; `None` when it has no function of its own.
29	    pub(crate) body: Option<Body>,
30	    /// Whether the listing follows the decision ([`narrow`]): off when every inherited prop is asked for expanded
31	    /// (`collapseInheritedProps: none`, ADR 0028's `relevance: 'all'`); the `used` lists are written either way.
32	    pub(crate) narrows: bool,
33	}
34	
35	/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
36	/// the members its listed props and layers reach; keeps the decision on the entry ([`ComponentEntry::relevance`]) and
37	/// lists by it ([`narrow`]).
38	pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
39	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
40	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance);
41	    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
42	    // A collapsed ambient member the signature defaults (`{ className = 'x' }`) is read by the body, which a row does
43	    // not record for a name left in its layer: it is `used` too. Nothing else in `rows` is added.
44	    let defaulted =
45	        members.iter().filter(|member| member.ambient && member.default_tag).map(|member| member.name.clone());
46	    // A row of a member the answer holds only as a name in a collapsed layer has no type to list: it is named in the
47	    // layer's `used` list instead, so a member evidence puts forward is never left unnamed.
48	    let untyped = shown
49	        .rows
50	        .iter()
51	        .filter(|name| !entry.props.contains_key(*name) && !entry.notable_inherited.contains_key(*name))
52	        .cloned();
53	    let used: BTreeSet<String> = shown.used.iter().cloned().chain(defaulted).chain(untyped).collect();
54	    // A `Pick` or `Omit` over keys that are not a closed set of literals leaves which members of a source reach
55	    // unproven, so no source is narrowed into a layer that may claim a member that does not reach; React's and the
56	    // DOM's attributes still are, as they are never listed for want of evidence.
57	    let ambient: BTreeSet<&str> =
58	        members.iter().filter(|member| member.ambient).map(|member| member.name.as_str()).collect();
59	    let declined = inputs.props_type.declined;
60	    let left = if inputs.narrows {
61	        let out = shown.collapsed.iter().chain(&shown.used);
62	        sources(entry, out.filter(|name| !declined || ambient.contains(name.as_str())))
63	    } else {
64	        BTreeSet::new()
65	    };
66	    entry.relevance = Some(std::sync::Arc::new(Placement { left, used }));
67	    narrow(entry);
68	}
69	
70	/// A member by provenance: its name and the source that declares it, by type name and file.
71	type Sourced = (String, String, String);
72	
73	/// Each of `names` with the source the structural answer gives it: the `parent` of the listed prop, and the layer of
74	/// each collapsed layer holding the name. A name the answer gives no source (a listed prop with no `parent`) has no
75	/// entry: its source is unknown, so no lane narrows it.
76	fn sources<'n>(entry: &ComponentEntry, names: impl Iterator<Item = &'n String>) -> BTreeSet<Sourced> {
77	    let mut sourced = BTreeSet::new();
78	    for name in names {
79	        let listed = entry.props.get(name).or_else(|| entry.notable_inherited.get(name));
80	        if let Some(parent) = listed.and_then(|prop| prop.parent.as_ref()) {
81	            sourced.insert((name.clone(), parent.name.clone(), parent.file_name.clone()));
82	        }
83	        for layer in entry.inheritance.iter().filter(|layer| layer.members.contains(name)) {
84	            sourced.insert((name.clone(), layer.type_name.clone(), layer.file_name.clone()));
85	        }
86	    }
87	    sourced
88	}
89	
90	/// What [`decide`] said of one component, kept on its entry so that every merge of the checker's props into it lists by
91	/// the same decision ([`narrow`]): the decision is made once, from the structural answer's evidence.
92	#[derive(Debug, Clone, Default, PartialEq, Eq)]
93	pub struct Placement {
94	    /// The members evidence leaves out of the listing ([`Shown::collapsed`] and [`Shown::used`]), each by name and
95	    /// the source the structural answer gives it: a listed prop is left out only when both match, so a prop of
96	    /// another source with the same name, or one the structural answer gave no source, is never hidden by it.
97	    left: BTreeSet<Sourced>,
98	    /// The members of `left` named in their layer's `used` list.
99	    used: BTreeSet<String>,
100	}
101	
102	/// Lists `entry` by its kept [`Placement`]: a listed prop (in `props` or `notableInherited`) the decision leaves out
103	/// and that a source outside the project declares (a dependency's, or React's and the DOM's) moves to the layer of
104	/// its source, as a name, when the placement left out that name from that same source. Its home is the layer of its
105	/// `parent` (by type name and file), else, for an ambient source, the entry's HTML element layer, else a new layer of
106	/// its `parent`. A prop with no `parent` has no known source and stays listed: no name is ever lost. Then each
107	/// layer's `used` list is written. Without a placement (no evidence was gathered) nothing changes. Run by [`apply`] and at the end of each merge of the
108	/// checker's props, which may list again what the structural answer left out.
109	pub(crate) fn narrow(entry: &mut ComponentEntry) {
110	    let Some(placement) = entry.relevance.clone() else { return };
111	    let ComponentEntry { props, notable_inherited, inheritance, .. } = entry;
112	    for listing in [props, notable_inherited] {
113	        listing.retain(|name, prop| {
114	            let Some(parent) = prop.parent.as_ref() else { return true };
115	            if !placement.left.contains(&(name.clone(), parent.name.clone(), parent.file_name.clone())) {
116	                return true;
117	            }
118	            // Only a source outside the project is narrowed: a dependency's or an ambient one, decided by the
119	            // declaring path. The project's own sources stay as the collapse rule lists them.
120	            if crate::origin::declaration_origin(&parent.file_name) == crate::origin::Origin::Project {
121	                return true;
122	            }
123	            // Each name is held once: a layer already holding it keeps it (`listed_props_leave_layers`' rule).
124	            if !inheritance.iter().any(|layer| layer.members.contains(name)) {
125	                home(inheritance, parent).members.push(name.clone());
126	            }
127	            false
128	        });
129	    }
130	    for layer in inheritance.iter_mut() {
131	        layer.total_props = layer.total_props.max(u32::try_from(layer.members.len()).unwrap_or(u32::MAX));
132	        layer.used = layer.members.iter().filter(|name| placement.used.contains(*name)).cloned().collect();
133	    }
134	}
135	
136	/// The layer a prop declared in `parent` is left in ([`narrow`]): made when the entry has none.
137	fn home<'l>(layers: &'l mut Vec<InheritedLayer>, parent: &PropParent) -> &'l mut InheritedLayer {
138	    let ambient = crate::origin::declaration_origin(&parent.file_name).is_ambient();
139	    let at = layers
140	        .iter()
141	        .position(|layer| layer.type_name == parent.name && layer.file_name == parent.file_name)
142	        .or_else(|| {
143	            ambient
144	                .then(|| {
145	                    layers.iter().position(|layer| {
146	                        layer.html_element.is_some() && crate::origin::declaration_origin(&layer.file_name).is_ambient()
147	                    })
148	                })
149	                .flatten()
150	        });
151	    let at = at.unwrap_or_else(|| {
152	        layers.push(InheritedLayer {
153	            type_name: parent.name.clone(),
154	            file_name: parent.file_name.clone(),
155	            omitted: Vec::new(),
156	            html_element: None,
157	            total_props: 0,
158	            members: Vec::new(),
159	            used: Vec::new(),
160	        });
161	        layers.len() - 1
162	    });
163	    &mut layers[at]
164	}
165	
166	/// Everything known about the members one component's props type reaches.
167	#[derive(Debug, Clone, Copy)]
168	pub(crate) struct Evidence<'a> {
169	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
170	    /// once, by its first member.
171	    pub(crate) members: &'a [Member],
172	    /// What the component's own function body does with its props; `None` when it has no function of its own.
173	    pub(crate) body: Option<&'a Body>,
174	    /// The props passed at the component's JSX call sites across the project.
175	    pub(crate) call_sites: &'a CallSites,
176	}
177	
178	/// One member the props type reaches, with the signals its declaration gives.
179	#[derive(Debug, Clone, Default, PartialEq, Eq)]
180	pub(crate) struct Member {
181	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
182	    pub(crate) name: String,
183	    /// The props type declares it itself, not through an inherited source.
184	    pub(crate) own: bool,
185	    /// A key a `Pick<X, …>` names.
186	    pub(crate) picked: bool,
187	    /// It redeclares or narrows a base member.
188	    pub(crate) overrides: bool,
189	    /// It is not optional.
190	    pub(crate) required: bool,
191	    /// Its declaration carries a `@default` tag.
192	    pub(crate) default_tag: bool,
193	    /// It carries a JSDoc comment: orders the rows, never shows a member.
194	    pub(crate) documented: bool,
195	    /// Its type is a union of literals: orders the rows, never shows a member.
196	    pub(crate) literal_union: bool,
197	    /// Declared by React's or the shared DOM declarations ([`crate::origin::Origin::is_ambient`]): decided by
198	    /// the declaring path, never by the name.
199	    pub(crate) ambient: bool,
200	}

