/// How many programs a whole-project run asks at once, each on a thread of the linked checker: a program's requests are
/// answered one at a time, and the checker's answering is what bounds the run (docs/gate-measurements.md).
const CHECKER_PROGRAMS: usize = 2;

/// The fewest files a program answers for: a project smaller than this asks one program, which builds no second checker
/// for a handful of components.
const MIN_FILES_PER_PROGRAM: usize = 32;

/// The file name an answer kept by [`resolve_cached`] has in the cache directory.
pub const KEPT_ANSWER_FILE: &str = kept::FILE;

/// A component the structural pass found.
pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;

/// The components of `output`, in output order, each of whose props is converted.
pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
    targets_with(output, None)
}

/// [`targets_of`] for an answer merged with `cx` ([`merge_semantic_in`](caliper_docgen_core::types::semantic::merge_semantic_in)
/// over this `output`): a prop the merge leaves to a collapsed layer is reported by name and `parent`, not converted
/// ([`Target::layering`]).
pub fn targets_collapsing(output: &ExtractionOutput, cx: CollapseContext) -> Vec<Target> {
    targets_with(output, Some(cx))
}

fn targets_with(output: &ExtractionOutput, cx: Option<CollapseContext>) -> Vec<Target> {
    output
        .components
        .iter()
        .map(|(key, entry)| Target {
            layering: cx.map(|cx| Layering::of(entry, cx)),
            key: key.clone(),
            file_path: entry.file_path.clone(),
            display_name: entry.display_name.clone(),
            exports: entry.exports.clone(),
            described: entry
                .props
                .values()
                .filter(|prop| !prop.description.is_empty())
                .map(|prop| prop.name.clone())
                .collect(),
            // Of `@types/react`'s props the whole-project merge keeps those the structural answer lists, as the
            // session does (`react_prop_listed`): relevance decided them there (ADR 0028, A2), so the checker reports
            // those names and converts no other DOM attribute.
            react_wanted: Some(entry.props.keys().cloned().collect()),
        })
        .collect()
}

/// What a run does with the memory and the checker's snapshot when it is done: free them, or leave them to the end of
/// the process.
///
/// Freeing a large project's converters, interner and snapshot one allocation at a time costs tens of milliseconds
/// that a process about to exit spends waiting for nothing. [`Teardown::OneShot`] is for that process alone (the CLI's
/// `extract`): it forgets what the run built instead of dropping it, and does not ask the checker to release its
/// snapshot, which the checker's shutdown takes down anyway. Anything that outlives the run (a watch, a Storybook
/// session, the binding, a command that keeps running) must use [`Teardown::Session`], which is the default.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Teardown {
    /// The process ends when the run does: forget the run's memory and do not release its snapshot.
    OneShot,
    /// The process goes on: free the run's memory and release its snapshot.
    #[default]
    Session,
}

/// One whole-project request to the checker: the components to answer for, and how to ask. Built with
/// [`SemanticRequest::new`] and answered by [`resolve`].
#[derive(Debug, Clone)]

