    let mut add = |name: &'n str, type_name: &str, file_name: &str| {
        if crate::origin::declaration_origin(file_name) != crate::origin::Origin::Project {
            sourced.entry((type_name.to_owned(), file_name.to_owned())).or_default().insert(name);
        }
    };

